class Solution:
    def mostProfitablePath(self, edges: List[List[int]], bob: int, amount: List[int]) -> int:
        n = len(amount)
        adj = [[] for _ in range(n)]
        for a, b in edges:
            adj[a].append(b)
            adj[b].append(a)

        parent = [-1] * n                        # BFS from the root to get parents
        order, seen = [0], {0}
        for u in order:
            for v in adj[u]:
                if v not in seen:
                    seen.add(v)
                    parent[v] = u
                    order.append(v)

        bob_time = {}                            # when Bob reaches each node on his way to the root
        node, t = bob, 0
        while node != -1:
            bob_time[node] = t
            node, t = parent[node], t + 1

        best = float("-inf")
        stack = [(0, -1, 0, 0)]                  # node, parent, Alice's arrival time, income so far
        while stack:
            u, p, t, income = stack.pop()
            if u not in bob_time or t < bob_time[u]:
                income += amount[u]              # Alice first: full amount
            elif t == bob_time[u]:
                income += amount[u] // 2         # same time: split (amounts are even)
            children = [v for v in adj[u] if v != p]
            if not children:
                best = max(best, income)         # a leaf (the root counts only if it has no children)
            for v in children:
                stack.append((v, u, t + 1, income))
        return best
